import { NextResponse } from 'next/server';
import type { ApiPostInput } from '@/types/blog';

interface RouteContext {
  params: Promise<{ id: string }> | { id: string };
}

function parsePostId(id: string): number | null {
  const parsed = Number.parseInt(id, 10);
  return Number.isNaN(parsed) ? null : parsed;
}

function parsePartialPostInput(value: unknown): Partial<ApiPostInput> | null {
  if (!value || typeof value !== 'object') {
    return {};
  }

  const payload = value as Partial<ApiPostInput>;

  if (payload.title !== undefined && typeof payload.title !== 'string') {
    return null;
  }

  if (payload.content !== undefined && typeof payload.content !== 'string') {
    return null;
  }

  return payload;
}

export async function GET(_request: Request, context: RouteContext) {
  const { id } = await context.params;
  const parsedId = parsePostId(id);

  if (parsedId === null) {
    return NextResponse.json({ error: 'Invalid post id' }, { status: 400 });
  }

  const post = {
    id: parsedId,
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  };

  return NextResponse.json(post);
}

export async function PUT(request: Request, context: RouteContext) {
  const { id } = await context.params;
  const parsedId = parsePostId(id);

  if (parsedId === null) {
    return NextResponse.json({ error: 'Invalid post id' }, { status: 400 });
  }

  let payload: unknown;

  try {
    payload = await request.json();
  } catch {
    return NextResponse.json({ error: 'Invalid JSON body' }, { status: 400 });
  }

  const input = parsePartialPostInput(payload);

  if (input === null) {
    return NextResponse.json(
      { error: 'title and content must be strings when provided' },
      { status: 400 },
    );
  }

  const updatedPost = {
    id: parsedId,
    title: input.title || `Post ${id}`,
    content: input.content || `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  };

  return NextResponse.json(updatedPost);
}

export async function DELETE(_request: Request, context: RouteContext) {
  const { id } = await context.params;
  const parsedId = parsePostId(id);

  if (parsedId === null) {
    return NextResponse.json({ error: 'Invalid post id' }, { status: 400 });
  }

  return NextResponse.json({ message: `Post ${id} deleted successfully` });
}

